\draw[mathred,->] (-1.6,0)--(-1.6,3);
\path (-1.6,1.5) node[left,text=mathred] {$15\text{ m/s}$};
\draw[black,thick,->] (0,0)--(-1.6,3);
\path (-0.55,1.8) node[right] {$17\text{ m/s}$};
\draw[black] (-0.6,0) arc[start angle=180,end angle=118.07,radius=0.6];
\path (-0.9,0.55) node {$\alpha$};
\end{tikzpicture}
[/tikz]
